contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public {
        uint256 betBefore = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 ethBefore = address(c).balance;

        c.AdjustDifficulty(amount); if (__ESBMC_reverted()) return;

        uint256 betAfter = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        uint256 ethAfter = address(c).balance;
        uint256 diffAfter = c.currentDifficulty(); if (__ESBMC_reverted()) return;

        assert(diffAfter == amount && betAfter == betBefore && ethAfter == ethBefore);
    }

    receive() external payable {}
}

