pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 amount) internal {
        uint256 betBefore;
        try c.currentBetLimit() returns (uint256 __r) { betBefore = __r; } catch { return; }
        uint256 ethBefore = address(c).balance;
        try c.AdjustDifficulty(amount) {} catch { return; }
        uint256 betAfter;
        try c.currentBetLimit() returns (uint256 __r) { betAfter = __r; } catch { return; }
        uint256 ethAfter = address(c).balance;
        uint256 diffAfter;
        try c.currentDifficulty() returns (uint256 __r) { diffAfter = __r; } catch { return; }
        assertTrue(diffAfter == amount && betAfter == betBefore && ethAfter == ethBefore);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
